template<class T>
class Box {
    T value;          // T 先当占位符
};

Box<int> a;      // 这里 T = int
Box<double> b;   // 这里 T = double

ChainNode<int> node(5);
ChainNode<int>* p = &node;

node.data;    // 对象用 .
p->data;      // 指针用 ->（等价于 (*p).data）

template<class T>
class Chain {
public:                    // 外面能调用
    void insert(int i, const T& x);
private:                   // 外面不能碰，只能内部用
    ChainNode<T>* firstNode;
    int listSize;
};

ArrayLinearList(int cap = 10) {   // 构造函数
    arrayLength = cap;
    element = new T[cap];
    listSize = 0;
}
~ArrayLinearList() {              // 析构函数
    delete[] element;
}

T** table = new T*[10];

table[0] = new T(5);   // 目录第 0 格指向一个元素
*table[0];             // 拿到 5
delete table[0];
delete[] table;

ChainNode<int>* p = nullptr;
if (p == nullptr) cout << "空";

while (p != nullptr) p = p->next;   // 遍历到尾巴

template<class T> class Chain;   // 前向声明

template<class T>
class ChainNode {
    friend class Chain<T>;       // Chain 可以访问我的私有成员
private:
    T data;
    ChainNode<T>* next;
};
